#include <iostream>

int main() {
    // Phase 1: Initialization
    int total = 0;        // Accumulator initialized to zero
    int counter = 0;      // Counter initialized to zero
    const int limit = 5;

    // Phase 2: Processing
    while (counter < limit) {
        int grade = 0;
        if (std::cin >> grade) {
            total += grade;
            ++counter;
        } else {
            break;
        }
    }

    // Phase 3: Termination
    if (counter > 0) {
        int average = total / counter; // Integer division
        std::cout << "Total: " << total << "\n";
        std::cout << "Count: " << counter << "\n";
        std::cout << "Class average is " << average << "\n";
    }

    return 0;
}

#include <iostream>

int main() {
    // Second refinement: Commit to specific variables
    int total = 0;
    int counter = 0;
    int grade = 0;

    // Priming read
    if (std::cin >> grade) {
        // Sentinel-controlled loop (sentinel value is -1)
        while (grade != -1) {
            total += grade;
            ++counter;

            // Read next grade
            if (!(std::cin >> grade)) {
                break;
            }
        }
    }

    // Termination phase with division-by-zero check
    if (counter != 0) {
        int average = total / counter;
        std::cout << "Total: " << total << "\n";
        std::cout << "Count: " << counter << "\n";
        std::cout << "Class average is " << average << "\n";
    } else {
        std::cout << "No grades were entered\n";
    }

    return 0;
}
